class Solution {
public:
    int minimumTime(vector<int>& hens, vector<int>& grains) {
        sort(hens.begin(), hens.end());
        sort(grains.begin(), grains.end());
        auto possible = [&](long long t) {
            int j = 0;
            for (int h : hens) {
                if (j == (int)grains.size()) return true;
                long long left = max(0LL, (long long)h - grains[j]);
                if (left > t) continue;
                long long reach = max((long long)h + (t - 2 * left),
                                      (long long)h + (t - left) / 2);
                while (j < (int)grains.size() && grains[j] <= reach) ++j;
            }
            return j == (int)grains.size();
        };
        long long lo = 0, hi = 2000000000LL;
        while (lo < hi) {
            long long mid = (lo + hi) / 2;
            if (possible(mid)) hi = mid;
            else lo = mid + 1;
        }
        return (int)lo;
    }
};
